<?php
require_once __DIR__.'/includes/db.php';require_once __DIR__.'/includes/auth.php';require_login();
$error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 $act=$_POST['action']??'';
 if($act==='add'){$eid=(int)($_POST['employee_id']??0);$start=$_POST['start_date']??'';$end=$_POST['end_date']??'';$type=trim($_POST['leave_type']??'Casual');$reason=trim($_POST['reason']??'');
 if(!$eid||!$start||!$end||$end<$start)$error='Choose an employee and valid leave dates.';
 else{$q=$pdo->prepare('INSERT INTO leave_records(employee_id,start_date,end_date,leave_type,reason) VALUES(?,?,?,?,?)');$q->execute([$eid,$start,$end,$type,$reason?:null]);$success='Leave record added with Pending status.';}}
 elseif($act==='status'){$status=$_POST['status']??'Pending';if(in_array($status,['Pending','Approved','Rejected'],true)){$q=$pdo->prepare('UPDATE leave_records SET status=? WHERE id=?');$q->execute([$status,(int)$_POST['id']]);$success='Leave status updated.';}}
}
$employees=$pdo->query('SELECT id,employee_code,full_name FROM employees ORDER BY full_name')->fetchAll();
$rows=$pdo->query('SELECT l.*,e.full_name,e.employee_code FROM leave_records l JOIN employees e ON e.id=l.employee_id ORDER BY l.created_at DESC')->fetchAll();
$page_title='Leave records | EIPS';require __DIR__.'/includes/header.php';?>
<div class="page-heading"><div><div class="eyebrow">LEAVE MANAGEMENT</div><h1>Leave records</h1><p class="muted">Record leave dates and track approval status.</p></div></div><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><?php if($success):?><div class="alert success"><?=e($success)?></div><?php endif;?>
<div class="two-col"><section class="panel"><div class="panel-heading"><div><h2>Add leave record</h2><p class="muted">New records start as Pending.</p></div></div><?php if(!$employees):?><p>Add an employee first.</p><?php else:?><form method="post" class="form-stack"><input type="hidden" name="action" value="add"><label>Employee *<select name="employee_id" required><option value="">Select employee</option><?php foreach($employees as $e1):?><option value="<?=(int)$e1['id']?>"><?=e($e1['employee_code'].' — '.$e1['full_name'])?></option><?php endforeach;?></select></label><label>Start date *<input type="date" name="start_date" required></label><label>End date *<input type="date" name="end_date" required></label><label>Leave type<select name="leave_type"><option>Casual</option><option>Sick</option><option>Earned</option><option>Other</option></select></label><label>Reason<input name="reason" placeholder="Optional reason"></label><button class="btn primary">Add leave</button></form><?php endif;?></section>
<section class="panel"><div class="panel-heading"><div><h2>Leave register</h2><p class="muted"><?=count($rows)?> record(s)</p></div></div><?php if(!$rows):?><div class="empty-state"><p>No leave records yet.</p></div><?php else:?><div class="table-wrap"><table><thead><tr><th>Employee</th><th>Dates</th><th>Type</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['full_name'])?></strong><small class="table-sub"><?=e($r['employee_code'])?></small></td><td><?=e($r['start_date'])?><small class="table-sub">to <?=e($r['end_date'])?></small></td><td><?=e($r['leave_type'])?></td><td><form method="post" class="status-form"><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><select name="status" onchange="this.form.submit()"><?php foreach(['Pending','Approved','Rejected'] as $s):?><option <?=$r['status']===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select></form></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section></div>
<?php require __DIR__.'/includes/footer.php';?>
